#!/usr/bin/env bash
set -euo pipefail

logfile="access.log"

if [[ ! -f $logfile ]]; then
    echo "top_talkers.sh: access.log not found" >&2
    exit 1
fi

awk '
{
    ip = $1
    if (ip == "") next

    if (!(ip in count)) {
        order[++n] = ip
    }
    count[ip]++
}
END {
    for (rank = 1; rank <= 3 && rank <= n; rank++) {
        best = ""
        best_count = -1

        # Iterate in first-appearance order.  Only replace best on a
        # strictly higher count, so an earlier IP wins ties.
        for (i = 1; i <= n; i++) {
            ip = order[i]
            if (selected[ip]) continue
            if (count[ip] > best_count) {
                best = ip
                best_count = count[ip]
            }
        }

        if (best != "") {
            print best
            selected[best] = 1
        }
    }
}
' "$logfile"
